    pub success: bool,
    pub exit_code: Option<i32>,
}

/// Status report output from `callisto status --format json`.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct StatusReport {
    pub schema_version: u32,
    /// Mandatory — the field the Action's mode dispatch reads.
    /// Always serialized, never omitted, even when `false`.
    pub has_changesets: bool,
    /// Count of packages with a planned bump (`StatusPackageRecord.pending_severity.is_some()`),
    /// i.e. post-cascade/fixed/linked-group -- unlike `has_changesets`, which only reflects
    /// changeset files directly naming a package. `status --check`'s
    /// exit code no longer signals pending state (0/1 gate on errors only), so this field is
    /// how a script detects it. Always serialized, even when `0`.
    pub pending: u32,
    pub packages: Vec<StatusPackageRecord>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub diagnostics: Vec<Diagnostic>,
}

impl Report for StatusReport {
    const COMMAND: &'static str = "status";

    fn schema_version(&self) -> u32 {
        self.schema_version
    }

    fn diagnostics(&self) -> &[Diagnostic] {
        &self.diagnostics
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct StatusPackageRecord {
    pub package: PackageId,
    pub current_version: Version,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub last_tag: Option<TagName>,

    pub last_released_version: Option<Version>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pending_severity: Option<Severity>,

    /// Mandatory, always serialized — empty-changeset validation and
    /// `changed_since_last_tag` consumers depend on this being present even
    /// when `false`.
    pub changed_since_last_tag: bool,

    pub release_trigger: ReleaseTrigger,

    pub pending_changesets: Vec<String>,
}

#[cfg(test)]
mod status_report_tests {
    use super::*;
    use crate::{PackageId, ReleaseTrigger, Version, VersionGrammar};

    fn pkg() -> PackageId {
        PackageId::parse("test-pkg").unwrap()
    }

    fn ver() -> Version {
        Version::parse("1.0.0", VersionGrammar::SemVer).unwrap()
    }

    fn record() -> StatusPackageRecord {
        StatusPackageRecord {
            package: pkg(),
            current_version: ver(),
            last_tag: None,
            last_released_version: None,
            pending_severity: None,
            changed_since_last_tag: false,
            release_trigger: ReleaseTrigger::Changeset,
            pending_changesets: vec![],
        }
    }

    /// `StatusReport.hasChangesets` is mandatory — the Action's mode dispatch
    /// reads it — so it must always be present in the serialized JSON, never
    /// omitted regardless of its value.
    #[test]
    fn status_report_json_always_contains_has_changesets() {
        let report = StatusReport {
            schema_version: SCHEMA_VERSION,
            has_changesets: false,
            pending: 0,
            packages: vec![],
            diagnostics: vec![],
        };
        let json = serde_json::to_string(&report).unwrap();
        assert!(
            json.contains("\"hasChangesets\":false"),
            "StatusReport JSON must always contain hasChangesets, even when false; got: {json}"
        );
    }

    /// `pending` (count of packages with a planned
    /// bump) must always serialize, including when `0` -- it's the field a
    /// script now reads to detect pending changesets, since `status --check`'s
    /// exit code no longer signals it.
    #[test]
    fn status_report_json_always_contains_pending() {
        let report = StatusReport {
            schema_version: SCHEMA_VERSION,
            has_changesets: false,
            pending: 0,
            packages: vec![],
            diagnostics: vec![],
        };
        let json = serde_json::to_string(&report).unwrap();
        assert!(
            json.contains("\"pending\":0"),
            "StatusReport JSON must always contain pending, even when 0; got: {json}"
}

/// Read-only managed release-pull-request subcommands.
#[derive(Subcommand, Clone, Debug)]
pub enum ReleasePrArgs {
    /// Derive create, update, or no-op from fresh workspace and forge facts.
    Decide(ReleasePrDecideArgs),
    /// Verify that a freshly collected forge snapshot still matches a prior decision.
    Verify(ReleasePrVerifyArgs),
    /// Build the exact forge commit-API file changes for the staged Git index.
    CommitPlan(ReleasePrCommitPlanArgs),
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePrDecideArgs {
    /// Versioned credential-free forge snapshot JSON, inline JSON, file path, or `-` for stdin.
    #[arg(long, value_name = "FILE|JSON|-")]
    pub snapshot: String,
    /// Exact configured forge repository identity, for example `orin-dx/callisto`.
    #[arg(long, value_name = "OWNER/REPOSITORY")]
    pub repository: String,
    /// Configured base branch for the managed release PR.
    #[arg(long)]
    pub base_branch: String,
    /// Canonical branch managed for the release PR.
    #[arg(long)]
    pub release_branch: String,
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePrVerifyArgs {
    /// Versioned decision JSON, inline JSON, file path, or `-` for stdin.
    #[arg(long, value_name = "FILE|JSON|-")]
    pub decision: String,
    /// Fresh versioned credential-free forge snapshot JSON, inline JSON, file path, or `-` for stdin.
    #[arg(long, value_name = "FILE|JSON|-")]
    pub snapshot: String,
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePrCommitPlanArgs {
    /// Full commit SHA the staged changes are relative to (the staging branch's root).
    #[arg(long)]
    pub base_commit: String,
    /// Commit message to record in the plan for the forge commit API.
    #[arg(long)]
    pub message: String,
    /// Write the plan to this file instead of stdout.
    #[arg(long, value_name = "FILE")]
    pub out: Option<PathBuf>,
}

#[derive(Args, Clone, Debug)]
pub struct ReleasePlanArgs {
    /// Read the release source from this checkout while the Callisto binary
    /// itself may come from a separate, current orchestration checkout.
//! Interface for typed managed release-pull-request decisions, and for
//! building the exact forge commit-API file changes the executor submits.
//! `decide` and `verify` are read-only; `commit-plan` reads the Git index
//! and worktree but writes no forge state itself -- the executor script is
//! the only thing that ever calls GitHub.

use std::process::ExitCode;

use callisto_graph::commands::{status, StatusOptions};
use callisto_model::vcs::GitAccess;
use callisto_model::{
    ApplyPermit, CommitSha, GitHubRepository, ReleasePrActionV2, ReleasePrCommitPlanReport, ReleasePrCommitPlanV1,
    ReleasePrConfigV1, ReleasePrDecideReport, ReleasePrDecisionError, ReleasePrDecisionV2, ReleasePrDecisionWireV2,
    ReleasePrSnapshotV2, ReleasePrSnapshotWireV2, ReleasePrVerifyReport,
};

use crate::cli::{
    GlobalArgs, OutputFormat, ReleasePrArgs, ReleasePrCommitPlanArgs, ReleasePrDecideArgs, ReleasePrVerifyArgs,
};
use crate::commands::read_json_arg;
use crate::error::CliError;
use crate::output::{emit_line, emit_report};
use crate::runner::CliCommandRunner;
use crate::workspace::load_workspace;

pub fn handle(args: ReleasePrArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    match args {
        ReleasePrArgs::Decide(args) => decide(args, global),
        ReleasePrArgs::Verify(args) => verify(args, global),
        ReleasePrArgs::CommitPlan(args) => commit_plan(args, global),
    }
}

/// Reads `flag`'s argument (file, inline JSON, or `-` for stdin) as an unvalidated wire
/// value. Kept separate from the domain type's own validating constructor so a JSON parse
/// failure (`E281`) and a domain validation failure (its own typed `E1xx` code) are never
/// folded into one generic error.
fn read_json_arg_as<T: serde::de::DeserializeOwned>(flag: &'static str, arg: &str) -> Result<T, CliError> {
    let text = read_json_arg(arg)?;
    serde_json::from_str(&text).map_err(|error| CliError::ReleasePrArgJsonInvalid {
        flag,
        detail: error.to_string(),
    })
}

fn verify(args: ReleasePrVerifyArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let decision_wire: ReleasePrDecisionWireV2 = read_json_arg_as("decision", &args.decision)?;
    let decision = ReleasePrDecisionV2::from_wire(decision_wire)?;
    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
    decision.verify_snapshot(&snapshot)?;
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleasePrVerifyReport { ok: true },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line("release PR decision still matches forge snapshot")?,
    }
    Ok(ExitCode::SUCCESS)
}

fn decide(args: ReleasePrDecideArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
    let repository =
        GitHubRepository::parse(&args.repository).map_err(|_error| ReleasePrDecisionError::InvalidRepository {
            repository: args.repository.clone(),
        })?;
    let config = ReleasePrConfigV1::new(repository, args.base_branch, args.release_branch)?;

    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let inference = crate::workspace::select_inference();
    let status = status(&workspace, &inference, &StatusOptions::default())?;
    let decision = ReleasePrDecisionV2::derive(status.has_changesets, &config, &snapshot)?;

    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &ReleasePrDecideReport { decision },
            global.dry_run,
        )?,
        OutputFormat::Text => render_decision(&decision)?,
    }
    Ok(ExitCode::SUCCESS)
}

fn commit_plan(args: ReleasePrCommitPlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let base_commit = CommitSha::parse(&args.base_commit)?;

    let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
        source,
        path: Some(global.cwd.clone()),
    })?;
    let runner = CliCommandRunner;
    let git = GitAccess::new(&start, &runner);
    let changes = git.staged_changes_since(&base_commit)?;
    let plan = ReleasePrCommitPlanV1::from_changes(base_commit, args.message, changes)?;

    match args.out {
        Some(path) => {
            let permit =
                ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleasePrCommitPlanDryRun)?;
            let content = serde_json::to_string_pretty(&plan).expect("commit plan serializes") + "\n";
            callisto_model::atomic::atomic_write(&path, &content, &permit).map_err(|source| CliError::Io {
                source,
                path: Some(path),
            })?;
        }
        None => emit_report(
            &mut std::io::stdout(),
            &ReleasePrCommitPlanReport { plan },
            global.dry_run,
        )?,
    }
    Ok(ExitCode::SUCCESS)
}

fn render_decision(decision: &ReleasePrDecisionV2) -> Result<(), CliError> {
        )));
    }
    Ok(())
}

/// Accepts every decision schema in [`ReleaseDecisionV1::READABLE_SCHEMA_VERSIONS`].
fn check_decision_schema_version<E: serde::de::Error>(found: u8, type_name: &str) -> Result<(), E> {
    if ReleaseDecisionV1::READABLE_SCHEMA_VERSIONS.contains(&found) {
        return Ok(());
    }
    Err(E::custom(format!(
        "unsupported {type_name} schema version {found}; this build reads versions {:?}",
        ReleaseDecisionV1::READABLE_SCHEMA_VERSIONS
    )))
}

/// Credential-free, deterministic release authority derived by callisto-graph.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleaseDecisionV1 {
    pub schema_version: u8,
    pub entries: Vec<ReleaseDecisionEntry>,
    pub digest: DecisionDigest,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseDecisionV1Wire {
    schema_version: u8,
    entries: Vec<ReleaseDecisionEntry>,
    digest: DecisionDigest,
}

impl<'de> Deserialize<'de> for ReleaseDecisionV1 {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseDecisionV1Wire::deserialize(deserializer)?;
        check_decision_schema_version::<D::Error>(wire.schema_version, "release decision")?;
        let decision = Self::new(wire.entries).map_err(serde::de::Error::custom)?;
        if decision.digest != wire.digest {
            return Err(serde::de::Error::custom(
                "release decision digest does not match canonical content",
            ));
        }
        Ok(decision)
    }
}

impl ReleaseDecisionV1 {
    pub const SCHEMA_VERSION: u8 = 2;
    /// Version 1 differs only in lacking `unreleasedVersion`, so a committed v1 decision still reads.
    pub const READABLE_SCHEMA_VERSIONS: [u8; 2] = [1, 2];

    /// Creates a canonical decision or rejects an ambiguous release roster.
    #[allow(clippy::result_large_err)]
    pub fn new(mut entries: Vec<ReleaseDecisionEntry>) -> Result<Self, ReleaseDecisionError> {
        if entries.is_empty() {
            return Err(ReleaseDecisionError::EmptyRoster);
        }
        for entry in &mut entries {
            entry.reasons.sort();
            entry.reasons.dedup();
            if entry.reasons.is_empty() {
                return Err(ReleaseDecisionError::MissingReason {
                    package: entry.package.clone(),
                });
            }
        }
